macro_rules! deps {
    () => {
        Anchored!();
        HalfMatch!();
        Prefilter!();
        DFA!();
        OverlappingState!();
        Config!();
        ByteSet!();
        Automaton!();
        MatchKind!();
        MatchError!();
        NFA!();
        Start!();
        Regex!();
        StartKind!();
        PatternID!();
        Input!();
    };
}

macro_rules! impl_12 {
    () => {
        deps!();
        # [cfg (feature = "dfa-build")] impl Config { # [doc = " Return a new default dense DFA compiler configuration."] pub fn new () -> Config { Config :: default () } # [doc = " Enable state acceleration."] # [doc = ""] # [doc = " When enabled, DFA construction will analyze each state to determine"] # [doc = " whether it is eligible for simple acceleration. Acceleration typically"] # [doc = " occurs when most of a state's transitions loop back to itself, leaving"] # [doc = " only a select few bytes that will exit the state. When this occurs,"] # [doc = " other routines like `memchr` can be used to look for those bytes which"] # [doc = " may be much faster than traversing the DFA."] # [doc = ""] # [doc = " Callers may elect to disable this if consistent performance is more"] # [doc = " desirable than variable performance. Namely, acceleration can sometimes"] # [doc = " make searching slower than it otherwise would be if the transitions"] # [doc = " that leave accelerated states are traversed frequently."] # [doc = ""] # [doc = " See [`Automaton::accelerator`] for an example."] # [doc = ""] # [doc = " This is enabled by default."] pub fn accelerate (mut self , yes : bool) -> Config { self . accelerate = Some (yes) ; self } # [doc = " Set a prefilter to be used whenever a start state is entered."] # [doc = ""] # [doc = " A [`Prefilter`] in this context is meant to accelerate searches by"] # [doc = " looking for literal prefixes that every match for the corresponding"] # [doc = " pattern (or patterns) must start with. Once a prefilter produces a"] # [doc = " match, the underlying search routine continues on to try and confirm"] # [doc = " the match."] # [doc = ""] # [doc = " Be warned that setting a prefilter does not guarantee that the search"] # [doc = " will be faster. While it's usually a good bet, if the prefilter"] # [doc = " produces a lot of false positive candidates (i.e., positions matched"] # [doc = " by the prefilter but not by the regex), then the overall result can"] # [doc = " be slower than if you had just executed the regex engine without any"] # [doc = " prefilters."] # [doc = ""] # [doc = " Note that unless [`Config::specialize_start_states`] has been"] # [doc = " explicitly set, then setting this will also enable (when `pre` is"] # [doc = " `Some`) or disable (when `pre` is `None`) start state specialization."] # [doc = " This occurs because without start state specialization, a prefilter"] # [doc = " is likely to be less effective. And without a prefilter, start state"] # [doc = " specialization is usually pointless."] # [doc = ""] # [doc = " **WARNING:** Note that prefilters are not preserved as part of"] # [doc = " serialization. Serializing a DFA will drop its prefilter."] # [doc = ""] # [doc = " By default no prefilter is set."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{dense::DFA, Automaton},"] # [doc = "     util::prefilter::Prefilter,"] # [doc = "     Input, HalfMatch, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let pre = Prefilter::new(MatchKind::LeftmostFirst, &[\"foo\", \"bar\"]);"] # [doc = " let re = DFA::builder()"] # [doc = "     .configure(DFA::config().prefilter(pre))"] # [doc = "     .build(r\"(foo|bar)[a-z]+\")?;"] # [doc = " let input = Input::new(\"foo1 barfox bar\");"] # [doc = " assert_eq!("] # [doc = "     Some(HalfMatch::must(0, 11)),"] # [doc = "     re.try_search_fwd(&input)?,"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Be warned though that an incorrect prefilter can lead to incorrect"] # [doc = " results!"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{dense::DFA, Automaton},"] # [doc = "     util::prefilter::Prefilter,"] # [doc = "     Input, HalfMatch, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let pre = Prefilter::new(MatchKind::LeftmostFirst, &[\"foo\", \"car\"]);"] # [doc = " let re = DFA::builder()"] # [doc = "     .configure(DFA::config().prefilter(pre))"] # [doc = "     .build(r\"(foo|bar)[a-z]+\")?;"] # [doc = " let input = Input::new(\"foo1 barfox bar\");"] # [doc = " assert_eq!("] # [doc = "     // No match reported even though there clearly is one!"] # [doc = "     None,"] # [doc = "     re.try_search_fwd(&input)?,"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn prefilter (mut self , pre : Option < Prefilter >) -> Config { self . pre = Some (pre) ; if self . specialize_start_states . is_none () { self . specialize_start_states = Some (self . get_prefilter () . is_some ()) ; } self } # [doc = " Minimize the DFA."] # [doc = ""] # [doc = " When enabled, the DFA built will be minimized such that it is as small"] # [doc = " as possible."] # [doc = ""] # [doc = " Whether one enables minimization or not depends on the types of costs"] # [doc = " you're willing to pay and how much you care about its benefits. In"] # [doc = " particular, minimization has worst case `O(n*k*logn)` time and `O(k*n)`"] # [doc = " space, where `n` is the number of DFA states and `k` is the alphabet"] # [doc = " size. In practice, minimization can be quite costly in terms of both"] # [doc = " space and time, so it should only be done if you're willing to wait"] # [doc = " longer to produce a DFA. In general, you might want a minimal DFA in"] # [doc = " the following circumstances:"] # [doc = ""] # [doc = " 1. You would like to optimize for the size of the automaton. This can"] # [doc = "    manifest in one of two ways. Firstly, if you're converting the"] # [doc = "    DFA into Rust code (or a table embedded in the code), then a minimal"] # [doc = "    DFA will translate into a corresponding reduction in code  size, and"] # [doc = "    thus, also the final compiled binary size. Secondly, if you are"] # [doc = "    building many DFAs and putting them on the heap, you'll be able to"] # [doc = "    fit more if they are smaller. Note though that building a minimal"] # [doc = "    DFA itself requires additional space; you only realize the space"] # [doc = "    savings once the minimal DFA is constructed (at which point, the"] # [doc = "    space used for minimization is freed)."] # [doc = " 2. You've observed that a smaller DFA results in faster match"] # [doc = "    performance. Naively, this isn't guaranteed since there is no"] # [doc = "    inherent difference between matching with a bigger-than-minimal"] # [doc = "    DFA and a minimal DFA. However, a smaller DFA may make use of your"] # [doc = "    CPU's cache more efficiently."] # [doc = " 3. You are trying to establish an equivalence between regular"] # [doc = "    languages. The standard method for this is to build a minimal DFA"] # [doc = "    for each language and then compare them. If the DFAs are equivalent"] # [doc = "    (up to state renaming), then the languages are equivalent."] # [doc = ""] # [doc = " Typically, minimization only makes sense as an offline process. That"] # [doc = " is, one might minimize a DFA before serializing it to persistent"] # [doc = " storage. In practical terms, minimization can take around an order of"] # [doc = " magnitude more time than compiling the initial DFA via determinization."] # [doc = ""] # [doc = " This option is disabled by default."] pub fn minimize (mut self , yes : bool) -> Config { self . minimize = Some (yes) ; self } # [doc = " Set the desired match semantics."] # [doc = ""] # [doc = " The default is [`MatchKind::LeftmostFirst`], which corresponds to the"] # [doc = " match semantics of Perl-like regex engines. That is, when multiple"] # [doc = " patterns would match at the same leftmost position, the pattern that"] # [doc = " appears first in the concrete syntax is chosen."] # [doc = ""] # [doc = " Currently, the only other kind of match semantics supported is"] # [doc = " [`MatchKind::All`]. This corresponds to classical DFA construction"] # [doc = " where all possible matches are added to the DFA."] # [doc = ""] # [doc = " Typically, `All` is used when one wants to execute an overlapping"] # [doc = " search and `LeftmostFirst` otherwise. In particular, it rarely makes"] # [doc = " sense to use `All` with the various \"leftmost\" find routines, since the"] # [doc = " leftmost routines depend on the `LeftmostFirst` automata construction"] # [doc = " strategy. Specifically, `LeftmostFirst` adds dead states to the DFA"] # [doc = " as a way to terminate the search and report a match. `LeftmostFirst`"] # [doc = " also supports non-greedy matches using this strategy where as `All`"] # [doc = " does not."] # [doc = ""] # [doc = " # Example: overlapping search"] # [doc = ""] # [doc = " This example shows the typical use of `MatchKind::All`, which is to"] # [doc = " report overlapping matches."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, OverlappingState, dense},"] # [doc = "     HalfMatch, Input, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new().match_kind(MatchKind::All))"] # [doc = "     .build_many(&[r\"\\w+$\", r\"\\S+$\"])?;"] # [doc = " let input = Input::new(\"@foo\");"] # [doc = " let mut state = OverlappingState::start();"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(1, 4));"] # [doc = " dfa.try_search_overlapping_fwd(&input, &mut state)?;"] # [doc = " assert_eq!(expected, state.get_match());"] # [doc = ""] # [doc = " // The first pattern also matches at the same position, so re-running"] # [doc = " // the search will yield another match. Notice also that the first"] # [doc = " // pattern is returned after the second. This is because the second"] # [doc = " // pattern begins its match before the first, is therefore an earlier"] # [doc = " // match and is thus reported first."] # [doc = " let expected = Some(HalfMatch::must(0, 4));"] # [doc = " dfa.try_search_overlapping_fwd(&input, &mut state)?;"] # [doc = " assert_eq!(expected, state.get_match());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: reverse automaton to find start of match"] # [doc = ""] # [doc = " Another example for using `MatchKind::All` is for constructing a"] # [doc = " reverse automaton to find the start of a match. `All` semantics are"] # [doc = " used for this in order to find the longest possible match, which"] # [doc = " corresponds to the leftmost starting position."] # [doc = ""] # [doc = " Note that if you need the starting position then"] # [doc = " [`dfa::regex::Regex`](crate::dfa::regex::Regex) will handle this for"] # [doc = " you, so it's usually not necessary to do this yourself."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{dense, Automaton, StartKind},"] # [doc = "     nfa::thompson::NFA,"] # [doc = "     Anchored, HalfMatch, Input, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let haystack = \"123foobar456\".as_bytes();"] # [doc = " let pattern = r\"[a-z]+r\";"] # [doc = ""] # [doc = " let dfa_fwd = dense::DFA::new(pattern)?;"] # [doc = " let dfa_rev = dense::Builder::new()"] # [doc = "     .thompson(NFA::config().reverse(true))"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         // This isn't strictly necessary since both anchored and"] # [doc = "         // unanchored searches are supported by default. But since"] # [doc = "         // finding the start-of-match only requires anchored searches,"] # [doc = "         // we can get rid of the unanchored configuration and possibly"] # [doc = "         // slim down our DFA considerably."] # [doc = "         .start_kind(StartKind::Anchored)"] # [doc = "         .match_kind(MatchKind::All)"] # [doc = "     )"] # [doc = "     .build(pattern)?;"] # [doc = " let expected_fwd = HalfMatch::must(0, 9);"] # [doc = " let expected_rev = HalfMatch::must(0, 3);"] # [doc = " let got_fwd = dfa_fwd.try_search_fwd(&Input::new(haystack))?.unwrap();"] # [doc = " // Here we don't specify the pattern to search for since there's only"] # [doc = " // one pattern and we're doing a leftmost search. But if this were an"] # [doc = " // overlapping search, you'd need to specify the pattern that matched"] # [doc = " // in the forward direction. (Otherwise, you might wind up finding the"] # [doc = " // starting position of a match of some other pattern.) That in turn"] # [doc = " // requires building the reverse automaton with starts_for_each_pattern"] # [doc = " // enabled. Indeed, this is what Regex does internally."] # [doc = " let input = Input::new(haystack)"] # [doc = "     .range(..got_fwd.offset())"] # [doc = "     .anchored(Anchored::Yes);"] # [doc = " let got_rev = dfa_rev.try_search_rev(&input)?.unwrap();"] # [doc = " assert_eq!(expected_fwd, got_fwd);"] # [doc = " assert_eq!(expected_rev, got_rev);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn match_kind (mut self , kind : MatchKind) -> Config { self . match_kind = Some (kind) ; self } # [doc = " The type of starting state configuration to use for a DFA."] # [doc = ""] # [doc = " By default, the starting state configuration is [`StartKind::Both`]."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{dense::DFA, Automaton, StartKind},"] # [doc = "     Anchored, HalfMatch, Input,"] # [doc = " };"] # [doc = ""] # [doc = " let haystack = \"quux foo123\";"] # [doc = " let expected = HalfMatch::must(0, 11);"] # [doc = ""] # [doc = " // By default, DFAs support both anchored and unanchored searches."] # [doc = " let dfa = DFA::new(r\"[0-9]+\")?;"] # [doc = " let input = Input::new(haystack);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&input)?);"] # [doc = ""] # [doc = " // But if we only need anchored searches, then we can build a DFA"] # [doc = " // that only supports anchored searches. This leads to a smaller DFA"] # [doc = " // (potentially significantly smaller in some cases), but a DFA that"] # [doc = " // will panic if you try to use it with an unanchored search."] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().start_kind(StartKind::Anchored))"] # [doc = "     .build(r\"[0-9]+\")?;"] # [doc = " let input = Input::new(haystack)"] # [doc = "     .range(8..)"] # [doc = "     .anchored(Anchored::Yes);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&input)?);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn start_kind (mut self , kind : StartKind) -> Config { self . start_kind = Some (kind) ; self } # [doc = " Whether to compile a separate start state for each pattern in the"] # [doc = " automaton."] # [doc = ""] # [doc = " When enabled, a separate **anchored** start state is added for each"] # [doc = " pattern in the DFA. When this start state is used, then the DFA will"] # [doc = " only search for matches for the pattern specified, even if there are"] # [doc = " other patterns in the DFA."] # [doc = ""] # [doc = " The main downside of this option is that it can potentially increase"] # [doc = " the size of the DFA and/or increase the time it takes to build the DFA."] # [doc = ""] # [doc = " There are a few reasons one might want to enable this (it's disabled"] # [doc = " by default):"] # [doc = ""] # [doc = " 1. When looking for the start of an overlapping match (using a"] # [doc = " reverse DFA), doing it correctly requires starting the reverse search"] # [doc = " using the starting state of the pattern that matched in the forward"] # [doc = " direction. Indeed, when building a [`Regex`](crate::dfa::regex::Regex),"] # [doc = " it will automatically enable this option when building the reverse DFA"] # [doc = " internally."] # [doc = " 2. When you want to use a DFA with multiple patterns to both search"] # [doc = " for matches of any pattern or to search for anchored matches of one"] # [doc = " particular pattern while using the same DFA. (Otherwise, you would need"] # [doc = " to compile a new DFA for each pattern.)"] # [doc = " 3. Since the start states added for each pattern are anchored, if you"] # [doc = " compile an unanchored DFA with one pattern while also enabling this"] # [doc = " option, then you can use the same DFA to perform anchored or unanchored"] # [doc = " searches. The latter you get with the standard search APIs. The former"] # [doc = " you get from the various `_at` search methods that allow you specify a"] # [doc = " pattern ID to search for."] # [doc = ""] # [doc = " By default this is disabled."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to use this option to permit the same DFA to"] # [doc = " run both anchored and unanchored searches for a single pattern."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{dense, Automaton},"] # [doc = "     Anchored, HalfMatch, PatternID, Input,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new().starts_for_each_pattern(true))"] # [doc = "     .build(r\"foo[0-9]+\")?;"] # [doc = " let haystack = \"quux foo123\";"] # [doc = ""] # [doc = " // Here's a normal unanchored search. Notice that we use 'None' for the"] # [doc = " // pattern ID. Since the DFA was built as an unanchored machine, it"] # [doc = " // use its default unanchored starting state."] # [doc = " let expected = HalfMatch::must(0, 11);"] # [doc = " let input = Input::new(haystack);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&input)?);"] # [doc = " // But now if we explicitly specify the pattern to search ('0' being"] # [doc = " // the only pattern in the DFA), then it will use the starting state"] # [doc = " // for that specific pattern which is always anchored. Since the"] # [doc = " // pattern doesn't have a match at the beginning of the haystack, we"] # [doc = " // find nothing."] # [doc = " let input = Input::new(haystack)"] # [doc = "     .anchored(Anchored::Pattern(PatternID::must(0)));"] # [doc = " assert_eq!(None, dfa.try_search_fwd(&input)?);"] # [doc = " // And finally, an anchored search is not the same as putting a '^' at"] # [doc = " // beginning of the pattern. An anchored search can only match at the"] # [doc = " // beginning of the *search*, which we can change:"] # [doc = " let input = Input::new(haystack)"] # [doc = "     .anchored(Anchored::Pattern(PatternID::must(0)))"] # [doc = "     .range(5..);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&input)?);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn starts_for_each_pattern (mut self , yes : bool) -> Config { self . starts_for_each_pattern = Some (yes) ; self } # [doc = " Whether to attempt to shrink the size of the DFA's alphabet or not."] # [doc = ""] # [doc = " This option is enabled by default and should never be disabled unless"] # [doc = " one is debugging a generated DFA."] # [doc = ""] # [doc = " When enabled, the DFA will use a map from all possible bytes to their"] # [doc = " corresponding equivalence class. Each equivalence class represents a"] # [doc = " set of bytes that does not discriminate between a match and a non-match"] # [doc = " in the DFA. For example, the pattern `[ab]+` has at least two"] # [doc = " equivalence classes: a set containing `a` and `b` and a set containing"] # [doc = " every byte except for `a` and `b`. `a` and `b` are in the same"] # [doc = " equivalence class because they never discriminate between a match and a"] # [doc = " non-match."] # [doc = ""] # [doc = " The advantage of this map is that the size of the transition table"] # [doc = " can be reduced drastically from `#states * 256 * sizeof(StateID)` to"] # [doc = " `#states * k * sizeof(StateID)` where `k` is the number of equivalence"] # [doc = " classes (rounded up to the nearest power of 2). As a result, total"] # [doc = " space usage can decrease substantially. Moreover, since a smaller"] # [doc = " alphabet is used, DFA compilation becomes faster as well."] # [doc = ""] # [doc = " **WARNING:** This is only useful for debugging DFAs. Disabling this"] # [doc = " does not yield any speed advantages. Namely, even when this is"] # [doc = " disabled, a byte class map is still used while searching. The only"] # [doc = " difference is that every byte will be forced into its own distinct"] # [doc = " equivalence class. This is useful for debugging the actual generated"] # [doc = " transitions because it lets one see the transitions defined on actual"] # [doc = " bytes instead of the equivalence classes."] pub fn byte_classes (mut self , yes : bool) -> Config { self . byte_classes = Some (yes) ; self } # [doc = " Heuristically enable Unicode word boundaries."] # [doc = ""] # [doc = " When set, this will attempt to implement Unicode word boundaries as if"] # [doc = " they were ASCII word boundaries. This only works when the search input"] # [doc = " is ASCII only. If a non-ASCII byte is observed while searching, then a"] # [doc = " [`MatchError::quit`](crate::MatchError::quit) error is returned."] # [doc = ""] # [doc = " A possible alternative to enabling this option is to simply use an"] # [doc = " ASCII word boundary, e.g., via `(?-u:\\b)`. The main reason to use this"] # [doc = " option is if you absolutely need Unicode support. This option lets one"] # [doc = " use a fast search implementation (a DFA) for some potentially very"] # [doc = " common cases, while providing the option to fall back to some other"] # [doc = " regex engine to handle the general case when an error is returned."] # [doc = ""] # [doc = " If the pattern provided has no Unicode word boundary in it, then this"] # [doc = " option has no effect. (That is, quitting on a non-ASCII byte only"] # [doc = " occurs when this option is enabled _and_ a Unicode word boundary is"] # [doc = " present in the pattern.)"] # [doc = ""] # [doc = " This is almost equivalent to setting all non-ASCII bytes to be quit"] # [doc = " bytes. The only difference is that this will cause non-ASCII bytes to"] # [doc = " be quit bytes _only_ when a Unicode word boundary is present in the"] # [doc = " pattern."] # [doc = ""] # [doc = " When enabling this option, callers _must_ be prepared to handle"] # [doc = " a [`MatchError`](crate::MatchError) error during search."] # [doc = " When using a [`Regex`](crate::dfa::regex::Regex), this corresponds"] # [doc = " to using the `try_` suite of methods. Alternatively, if"] # [doc = " callers can guarantee that their input is ASCII only, then a"] # [doc = " [`MatchError::quit`](crate::MatchError::quit) error will never be"] # [doc = " returned while searching."] # [doc = ""] # [doc = " This is disabled by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to heuristically enable Unicode word boundaries"] # [doc = " in a pattern. It also shows what happens when a search comes across a"] # [doc = " non-ASCII byte."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, dense},"] # [doc = "     HalfMatch, Input, MatchError,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new().unicode_word_boundary(true))"] # [doc = "     .build(r\"\\b[0-9]+\\b\")?;"] # [doc = ""] # [doc = " // The match occurs before the search ever observes the snowman"] # [doc = " // character, so no error occurs."] # [doc = " let haystack = \"foo 123  ☃\".as_bytes();"] # [doc = " let expected = Some(HalfMatch::must(0, 7));"] # [doc = " let got = dfa.try_search_fwd(&Input::new(haystack))?;"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " // Notice that this search fails, even though the snowman character"] # [doc = " // occurs after the ending match offset. This is because search"] # [doc = " // routines read one byte past the end of the search to account for"] # [doc = " // look-around, and indeed, this is required here to determine whether"] # [doc = " // the trailing \\b matches."] # [doc = " let haystack = \"foo 123 ☃\".as_bytes();"] # [doc = " let expected = MatchError::quit(0xE2, 8);"] # [doc = " let got = dfa.try_search_fwd(&Input::new(haystack));"] # [doc = " assert_eq!(Err(expected), got);"] # [doc = ""] # [doc = " // Another example is executing a search where the span of the haystack"] # [doc = " // we specify is all ASCII, but there is non-ASCII just before it. This"] # [doc = " // correctly also reports an error."] # [doc = " let input = Input::new(\"β123\").range(2..);"] # [doc = " let expected = MatchError::quit(0xB2, 1);"] # [doc = " let got = dfa.try_search_fwd(&input);"] # [doc = " assert_eq!(Err(expected), got);"] # [doc = ""] # [doc = " // And similarly for the trailing word boundary."] # [doc = " let input = Input::new(\"123β\").range(..3);"] # [doc = " let expected = MatchError::quit(0xCE, 3);"] # [doc = " let got = dfa.try_search_fwd(&input);"] # [doc = " assert_eq!(Err(expected), got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn unicode_word_boundary (mut self , yes : bool) -> Config { self . unicode_word_boundary = Some (yes) ; self } # [doc = " Add a \"quit\" byte to the DFA."] # [doc = ""] # [doc = " When a quit byte is seen during search time, then search will return"] # [doc = " a [`MatchError::quit`](crate::MatchError::quit) error indicating the"] # [doc = " offset at which the search stopped."] # [doc = ""] # [doc = " A quit byte will always overrule any other aspects of a regex. For"] # [doc = " example, if the `x` byte is added as a quit byte and the regex `\\w` is"] # [doc = " used, then observing `x` will cause the search to quit immediately"] # [doc = " despite the fact that `x` is in the `\\w` class."] # [doc = ""] # [doc = " This mechanism is primarily useful for heuristically enabling certain"] # [doc = " features like Unicode word boundaries in a DFA. Namely, if the input"] # [doc = " to search is ASCII, then a Unicode word boundary can be implemented"] # [doc = " via an ASCII word boundary with no change in semantics. Thus, a DFA"] # [doc = " can attempt to match a Unicode word boundary but give up as soon as it"] # [doc = " observes a non-ASCII byte. Indeed, if callers set all non-ASCII bytes"] # [doc = " to be quit bytes, then Unicode word boundaries will be permitted when"] # [doc = " building DFAs. Of course, callers should enable"] # [doc = " [`Config::unicode_word_boundary`] if they want this behavior instead."] # [doc = " (The advantage being that non-ASCII quit bytes will only be added if a"] # [doc = " Unicode word boundary is in the pattern.)"] # [doc = ""] # [doc = " When enabling this option, callers _must_ be prepared to handle a"] # [doc = " [`MatchError`](crate::MatchError) error during search. When using a"] # [doc = " [`Regex`](crate::dfa::regex::Regex), this corresponds to using the"] # [doc = " `try_` suite of methods."] # [doc = ""] # [doc = " By default, there are no quit bytes set."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This panics if heuristic Unicode word boundaries are enabled and any"] # [doc = " non-ASCII byte is removed from the set of quit bytes. Namely, enabling"] # [doc = " Unicode word boundaries requires setting every non-ASCII byte to a quit"] # [doc = " byte. So if the caller attempts to undo any of that, then this will"] # [doc = " panic."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to cause a search to terminate if it sees a"] # [doc = " `\\n` byte. This could be useful if, for example, you wanted to prevent"] # [doc = " a user supplied pattern from matching across a line boundary."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{dfa::{Automaton, dense}, Input, MatchError};"] # [doc = ""] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new().quit(b'\\n', true))"] # [doc = "     .build(r\"foo\\p{any}+bar\")?;"] # [doc = ""] # [doc = " let haystack = \"foo\\nbar\".as_bytes();"] # [doc = " // Normally this would produce a match, since \\p{any} contains '\\n'."] # [doc = " // But since we instructed the automaton to enter a quit state if a"] # [doc = " // '\\n' is observed, this produces a match error instead."] # [doc = " let expected = MatchError::quit(b'\\n', 3);"] # [doc = " let got = dfa.try_search_fwd(&Input::new(haystack)).unwrap_err();"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn quit (mut self , byte : u8 , yes : bool) -> Config { if self . get_unicode_word_boundary () && ! byte . is_ascii () && ! yes { panic ! ("cannot set non-ASCII byte to be non-quit when \
                 Unicode word boundaries are enabled") ; } if self . quitset . is_none () { self . quitset = Some (ByteSet :: empty ()) ; } if yes { self . quitset . as_mut () . unwrap () . add (byte) ; } else { self . quitset . as_mut () . unwrap () . remove (byte) ; } self } # [doc = " Enable specializing start states in the DFA."] # [doc = ""] # [doc = " When start states are specialized, an implementor of a search routine"] # [doc = " using a lazy DFA can tell when the search has entered a starting state."] # [doc = " When start states aren't specialized, then it is impossible to know"] # [doc = " whether the search has entered a start state."] # [doc = ""] # [doc = " Ideally, this option wouldn't need to exist and we could always"] # [doc = " specialize start states. The problem is that start states can be quite"] # [doc = " active. This in turn means that an efficient search routine is likely"] # [doc = " to ping-pong between a heavily optimized hot loop that handles most"] # [doc = " states and to a less optimized specialized handling of start states."] # [doc = " This causes branches to get heavily mispredicted and overall can"] # [doc = " materially decrease throughput. Therefore, specializing start states"] # [doc = " should only be enabled when it is needed."] # [doc = ""] # [doc = " Knowing whether a search is in a start state is typically useful when a"] # [doc = " prefilter is active for the search. A prefilter is typically only run"] # [doc = " when in a start state and a prefilter can greatly accelerate a search."] # [doc = " Therefore, the possible cost of specializing start states is worth it"] # [doc = " in this case. Otherwise, if you have no prefilter, there is likely no"] # [doc = " reason to specialize start states."] # [doc = ""] # [doc = " This is disabled by default, but note that it is automatically"] # [doc = " enabled (or disabled) if [`Config::prefilter`] is set. Namely, unless"] # [doc = " `specialize_start_states` has already been set, [`Config::prefilter`]"] # [doc = " will automatically enable or disable it based on whether a prefilter"] # [doc = " is present or not, respectively. This is done because a prefilter's"] # [doc = " effectiveness is rooted in being executed whenever the DFA is in a"] # [doc = " start state, and that's only possible to do when they are specialized."] # [doc = ""] # [doc = " Note that it is plausibly reasonable to _disable_ this option"] # [doc = " explicitly while _enabling_ a prefilter. In that case, a prefilter"] # [doc = " will still be run at the beginning of a search, but never again. This"] # [doc = " in theory could strike a good balance if you're in a situation where a"] # [doc = " prefilter is likely to produce many false positive candidates."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to enable start state specialization and then"] # [doc = " shows how to check whether a state is a start state or not."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, dense::DFA}, Input};"] # [doc = ""] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().specialize_start_states(true))"] # [doc = "     .build(r\"[a-z]+\")?;"] # [doc = ""] # [doc = " let haystack = \"123 foobar 4567\".as_bytes();"] # [doc = " let sid = dfa.start_state_forward(&Input::new(haystack))?;"] # [doc = " // The ID returned by 'start_state_forward' will always be tagged as"] # [doc = " // a start state when start state specialization is enabled."] # [doc = " assert!(dfa.is_special_state(sid));"] # [doc = " assert!(dfa.is_start_state(sid));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Compare the above with the default DFA configuration where start states"] # [doc = " are _not_ specialized. In this case, the start state is not tagged at"] # [doc = " all:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, dense::DFA}, Input};"] # [doc = ""] # [doc = " let dfa = DFA::new(r\"[a-z]+\")?;"] # [doc = ""] # [doc = " let haystack = \"123 foobar 4567\";"] # [doc = " let sid = dfa.start_state_forward(&Input::new(haystack))?;"] # [doc = " // Start states are not special in the default configuration!"] # [doc = " assert!(!dfa.is_special_state(sid));"] # [doc = " assert!(!dfa.is_start_state(sid));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn specialize_start_states (mut self , yes : bool) -> Config { self . specialize_start_states = Some (yes) ; self } # [doc = " Set a size limit on the total heap used by a DFA."] # [doc = ""] # [doc = " This size limit is expressed in bytes and is applied during"] # [doc = " determinization of an NFA into a DFA. If the DFA's heap usage, and only"] # [doc = " the DFA, exceeds this configured limit, then determinization is stopped"] # [doc = " and an error is returned."] # [doc = ""] # [doc = " This limit does not apply to auxiliary storage used during"] # [doc = " determinization that isn't part of the generated DFA."] # [doc = ""] # [doc = " This limit is only applied during determinization. Currently, there is"] # [doc = " no way to post-pone this check to after minimization if minimization"] # [doc = " was enabled."] # [doc = ""] # [doc = " The total limit on heap used during determinization is the sum of the"] # [doc = " DFA and determinization size limits."] # [doc = ""] # [doc = " The default is no limit."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows a DFA that fails to build because of a configured"] # [doc = " size limit. This particular example also serves as a cautionary tale"] # [doc = " demonstrating just how big DFAs with large Unicode character classes"] # [doc = " can get."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{dfa::{dense, Automaton}, Input};"] # [doc = ""] # [doc = " // 6MB isn't enough!"] # [doc = " dense::Builder::new()"] # [doc = "     .configure(dense::Config::new().dfa_size_limit(Some(6_000_000)))"] # [doc = "     .build(r\"\\w{20}\")"] # [doc = "     .unwrap_err();"] # [doc = ""] # [doc = " // ... but 7MB probably is!"] # [doc = " // (Note that DFA sizes aren't necessarily stable between releases.)"] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new().dfa_size_limit(Some(7_000_000)))"] # [doc = "     .build(r\"\\w{20}\")?;"] # [doc = " let haystack = \"A\".repeat(20).into_bytes();"] # [doc = " assert!(dfa.try_search_fwd(&Input::new(&haystack))?.is_some());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " While one needs a little more than 6MB to represent `\\w{20}`, it"] # [doc = " turns out that you only need a little more than 6KB to represent"] # [doc = " `(?-u:\\w{20})`. So only use Unicode if you need it!"] # [doc = ""] # [doc = " As with [`Config::determinize_size_limit`], the size of a DFA is"] # [doc = " influenced by other factors, such as what start state configurations"] # [doc = " to support. For example, if you only need unanchored searches and not"] # [doc = " anchored searches, then configuring the DFA to only support unanchored"] # [doc = " searches can reduce its size. By default, DFAs support both unanchored"] # [doc = " and anchored searches."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{dfa::{dense, Automaton, StartKind}, Input};"] # [doc = ""] # [doc = " // 3MB isn't enough!"] # [doc = " dense::Builder::new()"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         .dfa_size_limit(Some(3_000_000))"] # [doc = "         .start_kind(StartKind::Unanchored)"] # [doc = "     )"] # [doc = "     .build(r\"\\w{20}\")"] # [doc = "     .unwrap_err();"] # [doc = ""] # [doc = " // ... but 4MB probably is!"] # [doc = " // (Note that DFA sizes aren't necessarily stable between releases.)"] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         .dfa_size_limit(Some(4_000_000))"] # [doc = "         .start_kind(StartKind::Unanchored)"] # [doc = "     )"] # [doc = "     .build(r\"\\w{20}\")?;"] # [doc = " let haystack = \"A\".repeat(20).into_bytes();"] # [doc = " assert!(dfa.try_search_fwd(&Input::new(&haystack))?.is_some());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn dfa_size_limit (mut self , bytes : Option < usize >) -> Config { self . dfa_size_limit = Some (bytes) ; self } # [doc = " Set a size limit on the total heap used by determinization."] # [doc = ""] # [doc = " This size limit is expressed in bytes and is applied during"] # [doc = " determinization of an NFA into a DFA. If the heap used for auxiliary"] # [doc = " storage during determinization (memory that is not in the DFA but"] # [doc = " necessary for building the DFA) exceeds this configured limit, then"] # [doc = " determinization is stopped and an error is returned."] # [doc = ""] # [doc = " This limit does not apply to heap used by the DFA itself."] # [doc = ""] # [doc = " The total limit on heap used during determinization is the sum of the"] # [doc = " DFA and determinization size limits."] # [doc = ""] # [doc = " The default is no limit."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows a DFA that fails to build because of a"] # [doc = " configured size limit on the amount of heap space used by"] # [doc = " determinization. This particular example complements the example for"] # [doc = " [`Config::dfa_size_limit`] by demonstrating that not only does Unicode"] # [doc = " potentially make DFAs themselves big, but it also results in more"] # [doc = " auxiliary storage during determinization. (Although, auxiliary storage"] # [doc = " is still not as much as the DFA itself.)"] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " # if !cfg!(target_pointer_width = \"64\") { return Ok(()); } // see #1039"] # [doc = " use regex_automata::{dfa::{dense, Automaton}, Input};"] # [doc = ""] # [doc = " // 700KB isn't enough!"] # [doc = " dense::Builder::new()"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         .determinize_size_limit(Some(700_000))"] # [doc = "     )"] # [doc = "     .build(r\"\\w{20}\")"] # [doc = "     .unwrap_err();"] # [doc = ""] # [doc = " // ... but 800KB probably is!"] # [doc = " // (Note that auxiliary storage sizes aren't necessarily stable between"] # [doc = " // releases.)"] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         .determinize_size_limit(Some(800_000))"] # [doc = "     )"] # [doc = "     .build(r\"\\w{20}\")?;"] # [doc = " let haystack = \"A\".repeat(20).into_bytes();"] # [doc = " assert!(dfa.try_search_fwd(&Input::new(&haystack))?.is_some());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Note that some parts of the configuration on a DFA can have a"] # [doc = " big impact on how big the DFA is, and thus, how much memory is"] # [doc = " used. For example, the default setting for [`Config::start_kind`] is"] # [doc = " [`StartKind::Both`]. But if you only need an anchored search, for"] # [doc = " example, then it can be much cheaper to build a DFA that only supports"] # [doc = " anchored searches. (Running an unanchored search with it would panic.)"] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " # if !cfg!(target_pointer_width = \"64\") { return Ok(()); } // see #1039"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{dense, Automaton, StartKind},"] # [doc = "     Anchored, Input,"] # [doc = " };"] # [doc = ""] # [doc = " // 200KB isn't enough!"] # [doc = " dense::Builder::new()"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         .determinize_size_limit(Some(200_000))"] # [doc = "         .start_kind(StartKind::Anchored)"] # [doc = "     )"] # [doc = "     .build(r\"\\w{20}\")"] # [doc = "     .unwrap_err();"] # [doc = ""] # [doc = " // ... but 300KB probably is!"] # [doc = " // (Note that auxiliary storage sizes aren't necessarily stable between"] # [doc = " // releases.)"] # [doc = " let dfa = dense::Builder::new()"] # [doc = "     .configure(dense::Config::new()"] # [doc = "         .determinize_size_limit(Some(300_000))"] # [doc = "         .start_kind(StartKind::Anchored)"] # [doc = "     )"] # [doc = "     .build(r\"\\w{20}\")?;"] # [doc = " let haystack = \"A\".repeat(20).into_bytes();"] # [doc = " let input = Input::new(&haystack).anchored(Anchored::Yes);"] # [doc = " assert!(dfa.try_search_fwd(&input)?.is_some());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn determinize_size_limit (mut self , bytes : Option < usize >) -> Config { self . determinize_size_limit = Some (bytes) ; self } # [doc = " Returns whether this configuration has enabled simple state"] # [doc = " acceleration."] pub fn get_accelerate (& self) -> bool { self . accelerate . unwrap_or (true) } # [doc = " Returns the prefilter attached to this configuration, if any."] pub fn get_prefilter (& self) -> Option < & Prefilter > { self . pre . as_ref () . unwrap_or (& None) . as_ref () } # [doc = " Returns whether this configuration has enabled the expensive process"] # [doc = " of minimizing a DFA."] pub fn get_minimize (& self) -> bool { self . minimize . unwrap_or (false) } # [doc = " Returns the match semantics set in this configuration."] pub fn get_match_kind (& self) -> MatchKind { self . match_kind . unwrap_or (MatchKind :: LeftmostFirst) } # [doc = " Returns the starting state configuration for a DFA."] pub fn get_starts (& self) -> StartKind { self . start_kind . unwrap_or (StartKind :: Both) } # [doc = " Returns whether this configuration has enabled anchored starting states"] # [doc = " for every pattern in the DFA."] pub fn get_starts_for_each_pattern (& self) -> bool { self . starts_for_each_pattern . unwrap_or (false) } # [doc = " Returns whether this configuration has enabled byte classes or not."] # [doc = " This is typically a debugging oriented option, as disabling it confers"] # [doc = " no speed benefit."] pub fn get_byte_classes (& self) -> bool { self . byte_classes . unwrap_or (true) } # [doc = " Returns whether this configuration has enabled heuristic Unicode word"] # [doc = " boundary support. When enabled, it is possible for a search to return"] # [doc = " an error."] pub fn get_unicode_word_boundary (& self) -> bool { self . unicode_word_boundary . unwrap_or (false) } # [doc = " Returns whether this configuration will instruct the DFA to enter a"] # [doc = " quit state whenever the given byte is seen during a search. When at"] # [doc = " least one byte has this enabled, it is possible for a search to return"] # [doc = " an error."] pub fn get_quit (& self , byte : u8) -> bool { self . quitset . map_or (false , | q | q . contains (byte)) } # [doc = " Returns whether this configuration will instruct the DFA to"] # [doc = " \"specialize\" start states. When enabled, the DFA will mark start states"] # [doc = " as \"special\" so that search routines using the DFA can detect when"] # [doc = " it's in a start state and do some kind of optimization (like run a"] # [doc = " prefilter)."] pub fn get_specialize_start_states (& self) -> bool { self . specialize_start_states . unwrap_or (false) } # [doc = " Returns the DFA size limit of this configuration if one was set."] # [doc = " The size limit is total number of bytes on the heap that a DFA is"] # [doc = " permitted to use. If the DFA exceeds this limit during construction,"] # [doc = " then construction is stopped and an error is returned."] pub fn get_dfa_size_limit (& self) -> Option < usize > { self . dfa_size_limit . unwrap_or (None) } # [doc = " Returns the determinization size limit of this configuration if one"] # [doc = " was set. The size limit is total number of bytes on the heap that"] # [doc = " determinization is permitted to use. If determinization exceeds this"] # [doc = " limit during construction, then construction is stopped and an error is"] # [doc = " returned."] # [doc = ""] # [doc = " This is different from the DFA size limit in that this only applies to"] # [doc = " the auxiliary storage used during determinization. Once determinization"] # [doc = " is complete, this memory is freed."] # [doc = ""] # [doc = " The limit on the total heap memory used is the sum of the DFA and"] # [doc = " determinization size limits."] pub fn get_determinize_size_limit (& self) -> Option < usize > { self . determinize_size_limit . unwrap_or (None) } # [doc = " Overwrite the default configuration such that the options in `o` are"] # [doc = " always used. If an option in `o` is not set, then the corresponding"] # [doc = " option in `self` is used. If it's not set in `self` either, then it"] # [doc = " remains not set."] pub (crate) fn overwrite (& self , o : Config) -> Config { Config { accelerate : o . accelerate . or (self . accelerate) , pre : o . pre . or_else (| | self . pre . clone ()) , minimize : o . minimize . or (self . minimize) , match_kind : o . match_kind . or (self . match_kind) , start_kind : o . start_kind . or (self . start_kind) , starts_for_each_pattern : o . starts_for_each_pattern . or (self . starts_for_each_pattern) , byte_classes : o . byte_classes . or (self . byte_classes) , unicode_word_boundary : o . unicode_word_boundary . or (self . unicode_word_boundary) , quitset : o . quitset . or (self . quitset) , specialize_start_states : o . specialize_start_states . or (self . specialize_start_states) , dfa_size_limit : o . dfa_size_limit . or (self . dfa_size_limit) , determinize_size_limit : o . determinize_size_limit . or (self . determinize_size_limit) , } } }
    };
}

impl_12!();